async function main({ params }) {
    const ret = {
        push_x_keyframes_infos: {},
        rotation_keyframes_infos: {}
    };

    try {
        // 参数校验
        if (!params.pre_timelines || !Array.isArray(params.pre_timelines) || params.pre_timelines.length === 0) {
            throw new Error("pre_timelines参数无效");
        }
        if (!params.main_timelines || !Array.isArray(params.main_timelines) || params.main_timelines.length === 0) {
            throw new Error("main_timelines参数无效");
        }
        if (!params.all_timeline || !Array.isArray(params.all_timeline) || params.all_timeline.length === 0) {
            throw new Error("all_timeline参数无效");
        }

        // 计算全部时间线的总时长
        const allTimelineStart = params.all_timeline[0].start;
        const allTimelineEnd = params.all_timeline[params.all_timeline.length - 1].end;
        const allTimelineDuration = allTimelineEnd - allTimelineStart;

        // 计算前置时间线的推入效果关键帧
        const preTimelineStart = params.pre_timelines[0].start;
        const preTimelineEnd = params.pre_timelines[params.pre_timelines.length - 1].end;

        const startOffset = Math.round(((preTimelineStart - allTimelineStart) / allTimelineDuration) * 100);
        const endOffset = Math.round(((preTimelineEnd - allTimelineStart) / allTimelineDuration) * 100);

        ret.push_x_keyframes_infos = {
            ctype: "KFTypePositionX",
            offset: `${startOffset}|${endOffset}`,
            values: "-500|-200"
        };

        // 计算旋转关键帧 - 基于整个时间线总时长
        const rotationOffsets = [];
        const rotationValues = [];

        // 48秒 = 48000000微秒，一个旋转轮回
        const rotationCycleDuration = 48000000;

        // 计算需要多少个48秒轮回
        const totalCycles = Math.ceil(allTimelineDuration / rotationCycleDuration);

        // 添加0%位置的关键帧
        rotationOffsets.push(0);
        rotationValues.push(0);

        let lastEndTime = 0; // 记录上一个周期的结束时间

        // 为每个轮回生成关键帧
        for (let i = 0; i < totalCycles; i++) {
            // 当前周期的开始时间
            const cycleStartTime = i * rotationCycleDuration;
            // 当前周期的结束时间
            const cycleEndTime = Math.min((i + 1) * rotationCycleDuration, allTimelineDuration);

            // 计算开始和结束位置的百分比
            const startPercent = Math.max(0, Math.min(Math.round((cycleStartTime / allTimelineDuration) * 100), 100));
            const endPercent = Math.max(0, Math.min(Math.round((cycleEndTime / allTimelineDuration) * 100), 100));

            // 计算当前周期的实际时长
            const cycleDuration = cycleEndTime - cycleStartTime;

            // 计算当前周期的旋转角度（按比例）
            let rotationValue;
            if (i < totalCycles - 1) {
                // 完整周期：360度
                rotationValue = 360;
            } else {
                // 最后一个周期：按比例计算旋转角度
                rotationValue = Math.round(360 * (cycleDuration / rotationCycleDuration));
            }

            // 添加周期结束时的旋转关键帧
            rotationOffsets.push(endPercent);
            rotationValues.push(rotationValue);

            // 如果不是最后一个周期，添加0度关键帧作为下一周期开始
            if (i < totalCycles - 1 && endPercent < 100) {
                rotationOffsets.push(endPercent);
                rotationValues.push(0);
            }

            lastEndTime = cycleEndTime;
        }

        // 确保最后一个关键帧在100%
        if (rotationOffsets[rotationOffsets.length - 1] < 100) {
            // 计算最后一段的旋转角度
            const finalDuration = allTimelineDuration - lastEndTime;
            const finalRotation = Math.round(360 * (finalDuration / rotationCycleDuration));

            rotationOffsets.push(100);
            rotationValues.push(finalRotation);
        }

        ret.rotation_keyframes_infos = {
            ctype: "KFTypeRotation",
            offset: rotationOffsets.join("|"),
            values: rotationValues.join("|")
        };

    } catch (error) {
        // 异常处理，返回错误信息
        ret.push_x_keyframes_infos = {
            ctype: "KFTypePositionX",
            offset: "0|100",
            values: "0|0"
        };
        ret.rotation_keyframes_infos = {
            ctype: "KFTypeRotation", 
            offset: "0|100",
            values: "0|360"
        };
    }

    return ret;
}

async function main({ params }: Args): Promise<Output> {
    const result: Output = {
      all_timelines: [],
      timelines: [],
      links: []
    };

    try {
      // 验证输入格式
      if (!params || !Array.isArray(params.outputList)) {
        throw new Error("输入格式错误：必须包含 outputList 数组");
      }

      // 如果没有输入数据，直接返回空结果
      if (params.outputList.length === 0) {
        return result;
      }

      let currentPosition = 0; // 当前时间线位置

      // 遍历每一组输入数据
      for (const group of params.outputList) {
        // 验证组数据格式
        if (!Array.isArray(group.timelines) || 
            !Array.isArray(group.all_timelines) || 
            group.all_timelines.length === 0) {
          throw new Error("组数据格式错误：必须包含 timelines 和 all_timelines");
        }

        // 获取当前组的完整时间线
        const groupTimeline = group.all_timelines[0];
        const groupDuration = groupTimeline.end - groupTimeline.start;

        // 处理当前组的每个时间段
        for (const segment of group.timelines) {
          // 计算时间段在合并后时间线中的位置
          const segmentDuration = segment.end - segment.start;
          const newSegment = {
            start: currentPosition,
            end: currentPosition + segmentDuration
          };

          // 添加到结果中
          result.timelines.push(newSegment);

          // 更新当前位置
          currentPosition = newSegment.end;
        }
      }

      // 生成完整时间线范围
      if (result.timelines.length > 0) {
        result.all_timelines.push({
          start: 0,
          end: result.timelines[result.timelines.length - 1].end
        });
      }

    } catch (err: any) {
      result.error = err.message ?? "处理时间线数据时发生未知错误";
    }

    return result;
  }
